import hashlib,json,re,subprocess
from pathlib import Path
root=Path(__file__).resolve().parents[1];bench=root/'docs/benchmarks';meta=json.loads((root/'artifacts/handshake-inline-candidate.json').read_text());memory=json.loads((bench/'2026-10-16-handshake-inline-memory.json').read_text())
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
record={'scope':'Cumulative allocator stack deltas between ready/dripped gates for the256-peer quiet diagnostic. Native PIE load base comes from the zero-offset executable mapping in the heap capture; GNU addr2line resolves retained function symbols from each exact frozen binary. Debug lines are stripped, so function names are attribution context, not source line evidence. Every profile row is summed against its header. Whole requested counts include fixed management overhead; only the Connection::drive stack isolates upgrade-box allocations. No CPU or timing claim.', 'source':Path(__file__).read_text(),'cases':[],'passed':False}
for role in ['before','selected']:
 case=next(c for c in memory['cases'] if c['connections']==256 and c['kind']==role);data=json.loads((root/case['trace']).read_text());events={e['event']:e for e in data['events']}
 binary=root/(meta['baseline']['path'] if role=='before' else str(Path(meta['directory'])/'war-relay'))
 def parse(path):
  text=path.read_text();header=re.match(r'heap profile:\s+(\d+):\s+(\d+)\s+\[\s*(\d+):\s*(\d+)\]',text);assert header
  rows={}
  for line in text.splitlines():
   m=re.match(r'\s*(\d+):\s*(\d+)\s*\[\s*(\d+):\s*(\d+)\]\s*@ (.*)',line)
   if m:rows[m[5]]=tuple(map(int,m.groups()[:4]))
  assert tuple(sum(v[i] for v in rows.values()) for i in range(4))==tuple(map(int,header.groups()))
  return text,rows
 first=Path(events['ready']['heap']['path']);last=Path(events['dripped']['heap']['path']);_,a=parse(first);text,b=parse(last)
 maps=[line.split() for line in text.splitlines() if str(binary) in line];zero=next(row for row in maps if row[2]=='00000000');base=int(zero[0].split('-')[0],16);end=max(int(row[0].split('-')[1],16) for row in maps)
 addresses=sorted({int(pc,16) for stack in b for pc in stack.split() if base<=int(pc,16)<end})
 output=subprocess.check_output(['addr2line','-f','-C','-e',str(binary),*[hex(pc-base) for pc in addresses]],text=True).splitlines();assert len(output)==2*len(addresses)
 symbols={address:output[2*i] for i,address in enumerate(addresses)};rows=[]
 for stack,values in b.items():
  old=a.get(stack,(0,0,0,0));objects,bytes_=values[2]-old[2],values[3]-old[3]
  if objects or bytes_:rows.append({'allocated_objects':objects,'allocated_bytes':bytes_,'native_symbols':[symbols[int(pc,16)] for pc in stack.split() if int(pc,16) in symbols]})
 drive=[row for row in rows if any('war_relay::server::Connection::drive' in name for name in row['native_symbols'])]
 totals={key:sum(row[key] for row in drive) for key in ['allocated_objects','allocated_bytes']}
 assert totals==({'allocated_objects':8192,'allocated_bytes':2359296} if role=='before' else {'allocated_objects':0,'allocated_bytes':0}),totals
 row={'kind':role,'binary_sha256':sha(binary),'trace':case['trace'],'trace_sha256':sha(root/case['trace']),'drive_allocations':totals,'top_stacks':sorted(rows,key=lambda r:r['allocated_objects'],reverse=True)[:12]}
 record['cases'].append(row)
record['passed']=True;(bench/'2026-10-16-handshake-inline-alloc-symbols.json').write_text(json.dumps(record,indent=2)+'\n');print(json.dumps([{'kind':c['kind'],'drive_allocations':c['drive_allocations']} for c in record['cases']]))
